import { character_damage, characterDamageBreakdown, StatTable } from "@/index";
import { aggregateTeam } from "@/team";

// Kol's Calc Template.xlsx v5.0.1, SHA256:
// 8456a9721cd043c94c8554856fc1b2b97adcf7dbf558adae1c06a30f10b5683b.
// Inputs are saved F-column totals and CS talent values; expectations are cached
// workbook outputs, preserved from the original parity suite, not generated by core.
it("matches Single Char!Q47, C7 and C8 with explicit inputs", () => {
  const stats = new StatTable(["BaseATK", 950.03], ["ATKPercent", .466],
    ["FlatATK", 311.234], ["CritRate", .45], ["CritDMG", 2.168]);
  const options = { element: "Dendro" as const, damageType: "Plunging" as const, motionValue: 1.2786 * 1.837 };
  expect(characterDamageBreakdown(options, stats).scalingValue).toBeCloseTo(1703.97798, 7);
  const result = aggregateTeam([{ id: "Q47", owner: "ayaka", damage: character_damage(options)(stats) }], 20);
  expect(result.teamDpr).toBeCloseTo(3466.876375, 5);
  expect(result.teamDps).toBeCloseTo(173.3438187, 5);
});
it("matches Team's saved hit rows and four-character DPR/DPS", () => {
  const furina = new StatTable(["BaseATK", 851], ["ATKPercent", .396], ["FlatATK", 344.314],
    ["CritRate", .242], ["CritDMG", 1.2942], ["NormalATKDMGBonus", .4]);
  const xingqiu = new StatTable(["BaseATK", 766.78], ["ATKPercent", .735], ["FlatATK", 344.314],
    ["CritRate", .691], ["CritDMG", 1.2932]);
  const kazuha = new StatTable(["BaseATK", 806.58], ["ATKPercent", .297], ["FlatATK", 555.3508],
    ["CritRate", .05], ["CritDMG", .6322]);
  const jean = new StatTable(["BaseATK", 693.18], ["ATKPercent", .099], ["FlatATK", 344.314],
    ["CritRate", .446], ["CritDMG", .6322]);
  const hit = (stats: StatTable, motionValue: number, instances = 1) =>
    character_damage({ element: "Physical", damageType: "Normal", motionValue, instances })(stats);
  const rows = [
    { id: "Q88", owner: "furina", damage: hit(furina, .484 * 1.837) },
    { id: "Q90", owner: "furina", damage: character_damage({ element: "Physical", damageType: "None", motionValue: 1.6 })(furina) },
    { id: "Q157", owner: "xingqiu", damage: hit(xingqiu, .4661 * 1.837) },
    { id: "Q226", owner: "kazuha", damage: hit(kazuha, .4498 * 1.837) },
    { id: "Q295", owner: "jean", damage: hit(jean, .4833 * 1.837, 2) },
  ];
  expect(rows[0].damage).toBeCloseTo(1098.222599, 5);
  expect(rows[1].damage).toBeCloseTo(1411.652512, 5);
  const result = aggregateTeam(rows, 27);
  // Team!C8:F8, G10:G12.
  expect(result.owners.furina.dpr).toBeCloseTo(2509.875111, 5);
  expect(result.owners.xingqiu.dpr).toBeCloseTo(1190.527458, 5);
  expect(result.owners.kazuha.dpr).toBeCloseTo(598.5473959, 5);
  expect(result.owners.jean.dpr).toBeCloseTo(1103.987391, 5);
  expect(result.teamDpr).toBeCloseTo(5402.937356, 5);
  expect(result.teamDps).toBeCloseTo(200.108791, 5);
  expect(Object.values(result.owners).reduce((sum, owner) => sum + owner.share, 0)).toBeCloseTo(1, 12);
});
